-- V11: 课程知识点说明补全（XLSX 216 节点）
-- 依据节点在图谱中的层级、父级语义与上下游关联，补充专业规范的文字说明，
-- 确保每个知识点（含最细粒度的末端叶节点）描述完整、清晰、可展示。

-- ============ 模块一：编程基础 ============
UPDATE knowledge_point SET description='Java 编程的入门模块，覆盖从语言概述、环境搭建、基本语法到流程控制、数组与方法的完整基础体系，是后续面向对象与核心 API 学习的前提。' WHERE kp_code='kp-m1-l1-001';
UPDATE knowledge_point SET description='介绍 Java 语言的起源、发展历程与版本演进，帮助学习者建立对语言定位和应用领域的整体认知，是进入 Java 世界的第一课。' WHERE kp_code='kp-m1-l2-001';
UPDATE knowledge_point SET description='归纳 Java 区别于其他语言的核心特性，理解这些特点是掌握 Java 设计思想与后续语法机制的基础。' WHERE kp_code='kp-m1-l2-002';
UPDATE knowledge_point SET description='Java 摒弃了指针、多重继承等易错特性，语法接近 C++ 但更简洁，内存由垃圾回收机制自动管理，降低了学习与使用门槛。' WHERE kp_code='kp-m1-l3-001';
UPDATE knowledge_point SET description='Java 以类与对象为基本构建单元，支持封装、继承、多态三大特性，程序由相互协作的对象组成，便于对现实业务建模。' WHERE kp_code='kp-m1-l3-002';
UPDATE knowledge_point SET description='Java 取消指针运算、提供字节码校验与安全管理机制，避免内存越界与恶意代码攻击，适合网络环境下的安全开发。' WHERE kp_code='kp-m1-l3-003';
UPDATE knowledge_point SET description='Java 源码编译为平台无关的字节码，由各平台的 JVM 解释执行，实现“一次编写、到处运行”，是 Java 得以广泛部署的关键能力。' WHERE kp_code='kp-m1-l3-004';
UPDATE knowledge_point SET description='Java 语言级内置多线程支持，通过 Thread 类与 synchronized 等同步机制即可编写并发程序，充分利用多核处理器提升性能。' WHERE kp_code='kp-m1-l3-005';
UPDATE knowledge_point SET description='Java 提供丰富的网络类库与 RMI 等分布式能力，程序可跨越网络获取资源、调用远端服务，适合构建 C/S 与分布式应用。' WHERE kp_code='kp-m1-l3-006';
UPDATE knowledge_point SET description='讲解开发 Java 程序前所需的环境准备，包括 JDK 的安装与系统环境变量的配置，是编写第一个程序的前置条件。' WHERE kp_code='kp-m1-l2-003';
UPDATE knowledge_point SET description='Java Development Kit（Java 开发工具包），包含编译器 javac、运行时 JRE、核心类库与调试工具，是开发 Java 程序的必备软件。' WHERE kp_code='kp-m1-l3-007';
UPDATE knowledge_point SET description='配置 JAVA_HOME、Path 与 CLASSPATH，使系统在任意目录下均可识别 java/javac 命令，是命令行编译运行程序的基础。' WHERE kp_code='kp-m1-l3-008';
UPDATE knowledge_point SET description='介绍从编写源文件到运行程序的完整流程，通过 HelloWorld 实例理解 Java 程序的基本结构与编译运行机制。' WHERE kp_code='kp-m1-l2-004';
UPDATE knowledge_point SET description='第一个 Java 程序，包含类的定义与 main 入口方法，输出“Hello World”，用于验证环境搭建正确并认识程序的基本骨架。' WHERE kp_code='kp-m1-l3-009';
UPDATE knowledge_point SET description='Java 源文件经编译器编译为字节码，再由 JVM 加载解释或即时编译执行，理解该机制是掌握跨平台性与性能优化的前提。' WHERE kp_code='kp-m1-l3-010';
UPDATE knowledge_point SET description='使用 javac 将 .java 源文件编译为 .class 字节码文件，编译期完成语法检查，生成的字节码可运行在任意 JVM 上。' WHERE kp_code='kp-m1-l4-001';
UPDATE knowledge_point SET description='Java Virtual Machine（Java 虚拟机），负责加载字节码、管理内存并解释/即时编译执行，是 Java 实现“一次编写、到处运行”的核心。' WHERE kp_code='kp-m1-l4-002';
UPDATE knowledge_point SET description='主流 Java 集成开发环境，集代码编辑、智能补全、重构、调试与版本管理于一体，熟练使用可显著提升开发效率。' WHERE kp_code='kp-m1-l2-005';
UPDATE knowledge_point SET description='从官网下载安装包并完成安装与首次启动配置，创建 Java 工程后即可开始编写代码，是使用 IDEA 开发的第一步。' WHERE kp_code='kp-m1-l3-011';
UPDATE knowledge_point SET description='在 IDEA 中创建项目、包与类，编写源码后直接点击运行按钮即可编译执行，相比命令行方式更直观高效。' WHERE kp_code='kp-m1-l3-012';
UPDATE knowledge_point SET description='IDEA 内置的 Debugger 调试器，通过断点暂停程序、单步执行并观察变量变化，是定位逻辑错误的核心手段。' WHERE kp_code='kp-m1-l3-013';
UPDATE knowledge_point SET description='在目标代码行号处点击设置断点，程序运行到该行即暂停，配合观察窗口可检查此时各变量的取值与程序状态。' WHERE kp_code='kp-m1-l4-003';
UPDATE knowledge_point SET description='以调试方式启动程序，提供 Step Over、Step Into、Resume 等操作逐行跟踪执行流程，直观还原程序的运行轨迹。' WHERE kp_code='kp-m1-l4-004';
UPDATE knowledge_point SET description='构成 Java 程序的最小语法单元集合，涵盖程序结构、注释、关键字、标识符、数据类型、变量与运算符，是编写一切代码的基石。' WHERE kp_code='kp-m1-l2-006';
UPDATE knowledge_point SET description='规范 Java 源文件的组织方式：package 声明、import 导入、类定义与 main 入口方法的排列次序，结构完整程序才能编译运行。' WHERE kp_code='kp-m1-l3-014';
UPDATE knowledge_point SET description='通过 package 关键字声明类所属的包，按目录层次组织类，避免命名冲突并实现访问权限的包级控制。' WHERE kp_code='kp-m1-l4-005';
UPDATE knowledge_point SET description='使用 import 语句引入其他包中的类或静态成员，简化全限定名书写，是复用 JDK 与第三方类库的基础。' WHERE kp_code='kp-m1-l4-006';
UPDATE knowledge_point SET description='以 class 关键字加类名定义类，类体中封装成员变量与成员方法，类是面向对象程序的基本构建单元。' WHERE kp_code='kp-m1-l4-007';
UPDATE knowledge_point SET description='main 方法是程序执行的起点，固定签名 public static void main(String[] args)，JVM 从此处开始解释执行字节码。' WHERE kp_code='kp-m1-l4-008';
UPDATE knowledge_point SET description='用于解释说明代码、提升可读性且不参与编译的文字，包括单行、多行与文档注释三种形式，是规范编码的必备习惯。' WHERE kp_code='kp-m1-l3-015';
UPDATE knowledge_point SET description='以 // 开头注释一行内容，常用于解释单条语句或临时屏蔽代码，编译器会忽略该行 // 之后的所有文字。' WHERE kp_code='kp-m1-l4-009';
UPDATE knowledge_point SET description='以 /* 开头、*/ 结尾，可跨多行注释整段代码，适合说明方法逻辑或屏蔽成块语句，注释内不允许再嵌套多行注释。' WHERE kp_code='kp-m1-l4-010';
UPDATE knowledge_point SET description='以 /** 开头、*/ 结尾，配合 javadoc 工具可生成 API 帮助文档，通过 @param、@return 等标签规范描述方法信息。' WHERE kp_code='kp-m1-l4-011';
UPDATE knowledge_point SET description='由语言预定义、具有特殊含义的保留单词（如 class、public、static），全部小写且不可用作标识符，是语法结构的组成要素。' WHERE kp_code='kp-m1-l3-016';
UPDATE knowledge_point SET description='程序中类名、变量名、方法名的命名符号，由字母、数字、下划线与 $ 组成，不能以数字开头或使用关键字，应遵循见名知义的规范。' WHERE kp_code='kp-m1-l3-017';
UPDATE knowledge_point SET description='Java 是强类型语言，每个数据都有明确类型，分为基本类型（八种）与引用类型两大类，类型决定了数据的取值范围与运算方式。' WHERE kp_code='kp-m1-l3-018';
UPDATE knowledge_point SET description='语言内置的八种原子类型：四种整数、两种浮点、字符与布尔，变量空间直接存放数值本身，占用空间固定且运算效率高。' WHERE kp_code='kp-m1-l4-012';
UPDATE knowledge_point SET description='表示无小数部分的整数，按存储空间分为 byte、short、int、long 四档，整数字面量默认为 int 类型，long 需加 L 后缀。' WHERE kp_code='kp-m1-l5-001';
UPDATE knowledge_point SET description='byte 占 1 字节 8 位，取值 -128 至 127 共 256 个数，适合节省内存的大数组场景，参与运算时自动提升为 int。' WHERE kp_code='kp-m1-l6-001';
UPDATE knowledge_point SET description='short 占 2 字节 16 位，取值 -32768 至 32767，表示范围介于 byte 与 int 之间，日常开发中较少直接使用。' WHERE kp_code='kp-m1-l6-002';
UPDATE knowledge_point SET description='int 占 4 字节 32 位，取值约 ±21 亿（-2^31 至 2^31-1），是整数运算的默认类型，超出范围会溢出需改用 long。' WHERE kp_code='kp-m1-l6-003';
UPDATE knowledge_point SET description='long 占 8 字节 64 位，取值约 ±9.2×10^18（-2^63 至 2^63-1），表示超出 int 范围的整数时使用，字面量须加 L 后缀。' WHERE kp_code='kp-m1-l6-004';
UPDATE knowledge_point SET description='整数可写作十进制、八进制（0 前缀）、十六进制（0x 前缀）及 Java 7 起的下划线分隔（如 1_000_000）多种形式，编译后统一为二进制存储。' WHERE kp_code='kp-m1-l6-005';
UPDATE knowledge_point SET description='表示带小数部分的实数，分 float 与 double 两档，采用 IEEE 754 二进制浮点标准，浮点字面量默认为 double 类型。' WHERE kp_code='kp-m1-l5-002';
UPDATE knowledge_point SET description='float 占 4 字节，有效数字约 7 位，取值约 ±3.4E38，表示 float 字面量须加 F 后缀，适用于精度要求不高的场景。' WHERE kp_code='kp-m1-l6-006';
UPDATE knowledge_point SET description='double 占 8 字节，有效数字约 15-16 位，取值约 ±1.8E308，是浮点运算的默认类型；注意二进制无法精确表示部分十进制小数。' WHERE kp_code='kp-m1-l6-007';
UPDATE knowledge_point SET description='char 占 2 字节，采用 Unicode 编码表示单个字符，可参与算术运算（按编码值计算），是理解字符串存储本质的基础。' WHERE kp_code='kp-m1-l5-003';
UPDATE knowledge_point SET description='字符可写作 ''a'' 字面量、''\u0041'' Unicode 转义及 ''\n''、''\t'' 等转义字符三种形式，均存储为对应的 16 位编码值。' WHERE kp_code='kp-m1-l6-008';
UPDATE knowledge_point SET description='boolean 表示逻辑真值类型，只取 true 与 false 两个值，用于条件判断与循环控制，不能与整数类型互相转换。' WHERE kp_code='kp-m1-l5-004';
UPDATE knowledge_point SET description='boolean 仅 true/false 两个取值，区别于 C 语言的 0/1 表示，是 if、while 等语句条件表达式的基础类型。' WHERE kp_code='kp-m1-l6-009';
UPDATE knowledge_point SET description='包括类、接口、数组与枚举等，变量存放的是对象的内存地址而非值本身，默认值为 null，与基本类型的传值机制不同。' WHERE kp_code='kp-m1-l4-013';
UPDATE knowledge_point SET description='不同类型混合运算或赋值时需要进行类型转换，分自动（隐式）提升与强制（显式）转换两类，规则由取值范围大小决定。' WHERE kp_code='kp-m1-l4-014';
UPDATE knowledge_point SET description='取值范围小的类型可自动提升为大类型（如 byte→int→long→double），转换由编译器隐式完成，不会损失精度。' WHERE kp_code='kp-m1-l5-005';
UPDATE knowledge_point SET description='大范围转小范围须加 (目标类型) 显式转换（如 double→int），可能截断高位导致精度丢失或数据溢出，使用时需谨慎评估。' WHERE kp_code='kp-m1-l5-006';
UPDATE knowledge_point SET description='内存中存储数据的基本单元，由类型、名称与值三要素构成，掌握变量定义与作用域规则是编写业务逻辑的前提。' WHERE kp_code='kp-m1-l2-007';
UPDATE knowledge_point SET description='在类或方法中按“类型 变量名”语法声明变量，可同时初始化赋值，变量在栈或堆中的存储位置由其声明位置决定。' WHERE kp_code='kp-m1-l3-019';
UPDATE knowledge_point SET description='变量声明包含三要素：类型决定占用的空间与运算方式、名称用于引用该存储单元、可选的初始化决定起始值。' WHERE kp_code='kp-m1-l4-015';
UPDATE knowledge_point SET description='声明同时赋初始值（如 int a = 10）可避免使用未初始化变量导致的编译错误，局部变量不会获得默认值必须显式初始化。' WHERE kp_code='kp-m1-l4-016';
UPDATE knowledge_point SET description='变量仅在声明它的代码块（大括号）内有效，离开作用域即销毁，理解作用域规则可避免命名冲突与非法引用。' WHERE kp_code='kp-m1-l3-020';
UPDATE knowledge_point SET description='成员变量作用域为整个类，局部变量仅限所在方法或代码块，同名时局部变量会遮蔽成员变量，需用 this 加以区分。' WHERE kp_code='kp-m1-l4-017';
UPDATE knowledge_point SET description='对变量与常量进行运算的符号集合，掌握算术、赋值、比较、逻辑、位与三元运算符的规则与优先级是构建表达式的基础。' WHERE kp_code='kp-m1-l2-008';
UPDATE knowledge_point SET description='包括 + - * / % 五种基本运算，注意整数相除取整、取模结果符号规则，以及 ++/-- 自增自减的前后缀差异。' WHERE kp_code='kp-m1-l3-021';
UPDATE knowledge_point SET description='基本赋值 = 及 +=、-=、*=、/= 等复合形式，复合赋值隐含强制类型转换（如 s += 1 等价于 s = (short)(s+1)）。' WHERE kp_code='kp-m1-l3-022';
UPDATE knowledge_point SET description='包括 > < >= <= == !=，结果为 boolean 值；注意 == 比较基本类型比值、比较引用类型比地址，字符串内容比较须用 equals。' WHERE kp_code='kp-m1-l3-023';
UPDATE knowledge_point SET description='包括 & | ! 与短路 && ||，短路运算左侧已能决定结果时不再计算右侧，可避免空指针等副作用，实践中优先使用短路形式。' WHERE kp_code='kp-m1-l3-024';
UPDATE knowledge_point SET description='按二进制位运算，包括 & | ^ ~ 及位移 << >> >>>，常用于底层优化、标志位与加解密场景，符号位处理是难点。' WHERE kp_code='kp-m1-l3-025';
UPDATE knowledge_point SET description='格式“条件 ? 值1 : 值2”，条件为真取值1否则取值2，是 if...else 的简化表达式，嵌套使用需注意可读性。' WHERE kp_code='kp-m1-l3-026';
UPDATE knowledge_point SET description='根据条件真假选择执行路径的流程控制语句，包括 if 系列与 switch，使程序具备分支判断能力。' WHERE kp_code='kp-m1-l2-009';
UPDATE knowledge_point SET description='基本形式 if(条件){...}，条件为真执行代码块否则跳过，是所有分支结构的最小组成单元。' WHERE kp_code='kp-m1-l3-027';
UPDATE knowledge_point SET description='条件为真执行 if 块否则执行 else 块，二者必选其一，实现两路分支选择结构。' WHERE kp_code='kp-m1-l3-028';
UPDATE knowledge_point SET description='多条件依次判断、命中即止的结构，else 兜底所有未匹配情形，适合区间判断与多级分级场景。' WHERE kp_code='kp-m1-l3-029';
UPDATE knowledge_point SET description='switch(表达式) 匹配各 case 值执行对应分支，须有 break 防止贯穿，default 处理未匹配值；Java 7 起支持 String 匹配。' WHERE kp_code='kp-m1-l3-030';
UPDATE knowledge_point SET description='在条件满足时重复执行代码块的流程控制语句，包括 while、do...while、for 及嵌套形式，是处理批量数据的基础。' WHERE kp_code='kp-m1-l2-010';
UPDATE knowledge_point SET description='先判断条件后执行循环体，条件为假时一次也不执行，适合循环次数不确定的场景，注意在体内更新条件避免死循环。' WHERE kp_code='kp-m1-l3-031';
UPDATE knowledge_point SET description='先执行一次循环体再判断条件，保证循环体至少执行一次，与 while 的区别在于判断时机，语法以分号结尾。' WHERE kp_code='kp-m1-l3-032';
UPDATE knowledge_point SET description='将初始化、条件判断、迭代更新集中于一行声明，适合已知次数的循环，是使用频率最高的循环结构。' WHERE kp_code='kp-m1-l3-033';
UPDATE knowledge_point SET description='循环体内再包含循环，外层每执行一次内层完整执行一轮，常用于二维数组与乘法表等场景，复杂度随层数呈乘积增长。' WHERE kp_code='kp-m1-l3-034';
UPDATE knowledge_point SET description='改变循环默认执行流程的语句：break 结束整个循环、continue 跳过本次进入下一次，也可配合标签实现多层跳转。' WHERE kp_code='kp-m1-l2-011';
UPDATE knowledge_point SET description='立即终止所在循环继续执行循环后代码，在 switch 中用于结束分支防止贯穿，也可通过标签跳出外层循环。' WHERE kp_code='kp-m1-l3-035';
UPDATE knowledge_point SET description='结束本轮循环体剩余语句，直接进入下一轮条件判断，常用于过滤跳过特定元素，但不结束整个循环。' WHERE kp_code='kp-m1-l3-036';
UPDATE knowledge_point SET description='存储同一类型多个元素的定长容器，通过索引访问元素，是 Java 处理批量数据最基础的数据结构，也是集合框架的前置知识。' WHERE kp_code='kp-m1-l2-012';
UPDATE knowledge_point SET description='声明数组类型变量并分配内存空间，分静态与动态两种初始化方式，数组长度创建后不可改变。' WHERE kp_code='kp-m1-l3-037';
UPDATE knowledge_point SET description='创建时直接列出所有元素（如 int[] a = {1,2,3}），长度由元素个数决定，适合已知全部数据的场景。' WHERE kp_code='kp-m1-l4-018';
UPDATE knowledge_point SET description='先指定长度由系统分配默认值（如 new int[5] 各元素初始为 0），再按需赋值，适合长度已知但数据后置的场景。' WHERE kp_code='kp-m1-l4-019';
UPDATE knowledge_point SET description='通过 arr[索引] 读写元素，索引从 0 开始至 length-1，配合循环可遍历全部元素，越界访问将抛出异常。' WHERE kp_code='kp-m1-l3-038';
UPDATE knowledge_point SET description='使用数组时的两类典型运行时异常，理解其触发条件是编写健壮数组代码的前提。' WHERE kp_code='kp-m1-l3-039';
UPDATE knowledge_point SET description='访问索引小于 0 或大于等于 length 时抛出 ArrayIndexOutOfBoundsException，遍历时用 length 而非硬编码长度可避免。' WHERE kp_code='kp-m1-l4-020';
UPDATE knowledge_point SET description='数组引用为 null 时访问其元素抛出 NullPointerException，常因未初始化或已被置空导致，判空后再访问可预防。' WHERE kp_code='kp-m1-l4-021';
UPDATE knowledge_point SET description='数组的典型应用场景：求最值、统计、逆序、查找与冒泡/选择排序等基础算法练习，训练索引与循环的配合能力。' WHERE kp_code='kp-m1-l3-040';
UPDATE knowledge_point SET description='以一维数组为元素的数组，可视为行列矩阵，用于存储表格类数据，是理解多维存储与嵌套循环的综合应用。' WHERE kp_code='kp-m1-l3-041';
UPDATE knowledge_point SET description='支持 int[][] a = {{1,2},{3,4}} 规则式与 new int[2][3] 动态式（含可变列长的锯齿数组）两种定义形式。' WHERE kp_code='kp-m1-l4-022';
UPDATE knowledge_point SET description='通过 arr[行][列] 双索引访问元素，配合双层循环遍历，arr.length 为行数、arr[i].length 为该行的列数。' WHERE kp_code='kp-m1-l4-023';
UPDATE knowledge_point SET description='封装特定功能代码段的命名单元，实现复用与模块化，包括定义、调用、重载与参数传递机制，是结构化编程的核心。' WHERE kp_code='kp-m1-l2-013';
UPDATE knowledge_point SET description='语法为“修饰符 返回类型 方法名(参数列表){方法体}”，遵循职责单一原则，return 返回结果并结束方法。' WHERE kp_code='kp-m1-l3-042';
UPDATE knowledge_point SET description='通过“方法名(实参)”执行封装的逻辑，形参接收实参值；基本类型传值拷贝、引用类型传地址，调用后控制权返回调用处。' WHERE kp_code='kp-m1-l3-043';
UPDATE knowledge_point SET description='同一类中方法名相同但参数个数或类型不同即构成重载，编译器按实参匹配最优版本，与返回值无关，是多态的雏形。' WHERE kp_code='kp-m1-l3-044';

-- ============ 模块二：类与对象基础 ============
UPDATE knowledge_point SET description='面向对象编程的奠基模块，从编程思维转变入手，讲解类与对象、封装、构造方法与 static 机制，为继承、多态等高阶特性打基础。' WHERE kp_code='kp-m2-l1-001';
UPDATE knowledge_point SET description='以“对象”为中心的编程思想，通过对比面向过程理解其优势，是整个 Java 语言设计的理论基础。' WHERE kp_code='kp-m2-l2-001';
UPDATE knowledge_point SET description='以过程/函数为中心，按步骤分解问题依次调用，数据与方法分离，适合小型任务但大型系统难以维护扩展。' WHERE kp_code='kp-m2-l3-001';
UPDATE knowledge_point SET description='以对象为中心，将数据与操作封装在类中，通过对象协作完成功能，具备复用、扩展与维护优势，适合大型软件建模。' WHERE kp_code='kp-m2-l3-002';
UPDATE knowledge_point SET description='封装隐藏细节、继承复用扩展、多态统一行为，三大特性相互配合构成面向对象设计的核心，后续语法均围绕其展开。' WHERE kp_code='kp-m2-l3-003';
UPDATE knowledge_point SET description='类是对象的模板与蓝图，对象是类的运行实例，理解二者的关系与内存分布是面向对象编程的起点。' WHERE kp_code='kp-m2-l2-002';
UPDATE knowledge_point SET description='通过 class 关键字定义类，类体中声明成员变量（属性）与成员方法（行为），是创建对象的模板。' WHERE kp_code='kp-m2-l3-004';
UPDATE knowledge_point SET description='类中方法外定义的属性，描述对象状态；有默认值（数值为 0、引用为 null），作用域为整个类，随对象存储在堆中。' WHERE kp_code='kp-m2-l4-001';
UPDATE knowledge_point SET description='类中定义的行为单元，通过操作成员变量实现对象功能，可被本类及其他类的对象调用，是对象对外提供服务的形式。' WHERE kp_code='kp-m2-l4-002';
UPDATE knowledge_point SET description='依据类模板在堆中开辟内存创建对象，通过引用访问其属性与方法，掌握声明、实例化、使用三步是操作对象的基本功。' WHERE kp_code='kp-m2-l3-005';
UPDATE knowledge_point SET description='“类名 对象名;” 在栈中定义引用变量，此时未分配对象内存，引用值为 null，尚不能访问成员。' WHERE kp_code='kp-m2-l4-003';
UPDATE knowledge_point SET description='使用 new 调用构造方法在堆中分配空间并完成初始化，将地址赋给引用变量，一个类可实例化多个相互独立的对象。' WHERE kp_code='kp-m2-l4-004';
UPDATE knowledge_point SET description='通过“对象名.属性”访问成员变量、“对象名.方法()”调用成员方法，各对象间相互独立互不干扰。' WHERE kp_code='kp-m2-l4-005';
UPDATE knowledge_point SET description='方法参数与方法返回传递的是引用（地址），多个引用可指向同一对象，通过任一引用修改都会影响该对象本身。' WHERE kp_code='kp-m2-l4-006';
UPDATE knowledge_point SET description='面向对象第一特性：隐藏内部实现细节仅对外暴露必要接口，配合访问控制保护数据安全，是类设计的基本原则。' WHERE kp_code='kp-m2-l2-003';
UPDATE knowledge_point SET description='将属性与行为聚合在类中并隐藏内部细节，仅通过公共方法与外界交互，降低耦合、提升安全性与可维护性。' WHERE kp_code='kp-m2-l3-006';
UPDATE knowledge_point SET description='将成员变量设为 private，外部无法直接访问修改，内部实现变化不影响调用方，是“高内聚低耦合”的体现。' WHERE kp_code='kp-m2-l4-007';
UPDATE knowledge_point SET description='通过 public 方法对外暴露受控的操作入口，方法内可校验入参合法性，保证对象状态始终有效。' WHERE kp_code='kp-m2-l4-008';
UPDATE knowledge_point SET description='通过访问修饰符限定类及其成员的可访问范围，实现分级可见性控制，是封装机制的具体实现手段。' WHERE kp_code='kp-m2-l3-007';
UPDATE knowledge_point SET description='四个级别：public 全公开、protected 同包与子类、默认（不写）仅同包、private 仅本类，按最小可见性原则选择使用。' WHERE kp_code='kp-m2-l4-009';
UPDATE knowledge_point SET description='标准封装三步：成员变量私有化 → 提供 public 的 getter/setter → 在方法中校验数据，是实体类编码的通用范式。' WHERE kp_code='kp-m2-l3-008';
UPDATE knowledge_point SET description='将属性声明为 private 防止外部随意赋值，是封装实现的第一步，配合公共方法实现受控读写。' WHERE kp_code='kp-m2-l4-010';
UPDATE knowledge_point SET description='提供 public 的 getXxx()/setXxx() 方法读写私有属性，setter 中可加入合法性校验，保证数据的有效性。' WHERE kp_code='kp-m2-l4-011';
UPDATE knowledge_point SET description='对象创建时自动调用的特殊方法，完成对象初始化；与类同名且无返回值，支持重载，分无参与有参两种形式。' WHERE kp_code='kp-m2-l2-004';
UPDATE knowledge_point SET description='方法名与类名相同、无返回类型、在 new 时自动调用；未显式定义时编译器提供默认无参构造，一旦自定义默认构造即消失。' WHERE kp_code='kp-m2-l3-009';
UPDATE knowledge_point SET description='在对象创建瞬间完成成员变量的初始化，保证对象一诞生即处于有效状态，是 new 操作“分配内存+调用构造”的第二步。' WHERE kp_code='kp-m2-l4-012';
UPDATE knowledge_point SET description='“修饰符 类名(参数列表){初始化代码}”，无参构造做空初始化、有参构造按实参初始化属性，是对象初始化的标准入口。' WHERE kp_code='kp-m2-l4-013';
UPDATE knowledge_point SET description='同时提供无参与多种参数形式的构造方法，编译器按实参自动匹配，为对象初始化提供灵活的多重入口。' WHERE kp_code='kp-m2-l3-010';
UPDATE knowledge_point SET description='重载要求参数个数或类型不同，通过不同入参组合完成不同粒度的初始化，本类构造之间可用 this(...) 互调复用。' WHERE kp_code='kp-m2-l4-014';
UPDATE knowledge_point SET description='有参构造在创建对象的同时按实参为属性赋值，替代先创建后多次 set 的繁琐写法，简化对象构建过程。' WHERE kp_code='kp-m2-l4-015';
UPDATE knowledge_point SET description='指向当前对象自身的引用，用于区分成员变量与局部变量、构造器互调及链式调用，是理解对象内部机制的关键。' WHERE kp_code='kp-m2-l3-011';
UPDATE knowledge_point SET description='this 保存当前对象的内存地址，谁调用该方法 this 就指向谁，在方法内部即“当前对象”的代称。' WHERE kp_code='kp-m2-l4-016';
UPDATE knowledge_point SET description='this.成员变量 区分重名局部变量、this.方法() 调用成员方法、this(...) 在构造方法首行调用本类其他构造。' WHERE kp_code='kp-m2-l4-017';
UPDATE knowledge_point SET description='“this.属性名” 强调访问的是成员变量而非同名形参，是 setter 方法中最典型的用法（this.name = name）。' WHERE kp_code='kp-m2-l5-001';
UPDATE knowledge_point SET description='“this.方法名()” 显式调用当前对象的方法，通常可省略 this，在方法互调需要明确当前对象时使用。' WHERE kp_code='kp-m2-l5-002';
UPDATE knowledge_point SET description='“this(实参)” 在构造方法第一行调用本类其他重载构造，实现初始化逻辑复用，且必须位于构造方法的首行。' WHERE kp_code='kp-m2-l5-003';
UPDATE knowledge_point SET description='将成员从对象级别提升为类级别，被所有对象共享且随类加载初始化，是理解生命周期与工具类设计的基础。' WHERE kp_code='kp-m2-l2-005';
UPDATE knowledge_point SET description='属于类而非对象的方法，随类加载即可用，直接以类名调用；内部只能访问静态成员，因为调用时可能尚无对象存在。' WHERE kp_code='kp-m2-l3-012';
UPDATE knowledge_point SET description='类加载时执行一次的 static{} 代码块，先于构造方法执行，常用于加载驱动、读取配置等仅需执行一次的初始化。' WHERE kp_code='kp-m2-l3-013';
UPDATE knowledge_point SET description='类级别的共享变量，所有对象共用一份、存储于方法区，可通过类名直接访问；实例变量则每个对象独立持有一份。' WHERE kp_code='kp-m2-l3-014';

-- ============ 模块三：面向对象高阶 ============
UPDATE knowledge_point SET description='深入面向对象三大特性的进阶模块，涵盖继承、抽象类、多态、接口、内部类与异常处理，是构建可扩展架构的核心知识。' WHERE kp_code='kp-m3-l1-001';
UPDATE knowledge_point SET description='子类复用父类属性与方法的机制，建立 is-a 关系，配合方法重写与 super 实现层次化设计，是面向对象三大特性之一。' WHERE kp_code='kp-m3-l2-001';
UPDATE knowledge_point SET description='实现代码复用与层次建模：共性抽取到父类、个性下沉到子类，修改父类一处即可影响全部子类，有效减少重复代码。' WHERE kp_code='kp-m3-l3-001';
UPDATE knowledge_point SET description='“class 子类 extends 父类”，Java 为单继承（一个直接父类）但可多层继承；构造器不被继承，子类构造默认先调用 super()。' WHERE kp_code='kp-m3-l3-002';
UPDATE knowledge_point SET description='子类按“两同两小一大”规则重新实现父类方法（方法名参数相同、返回值与异常范围更小、访问权限不小于父类），运行时执行实际类型版本。' WHERE kp_code='kp-m3-l3-003';
UPDATE knowledge_point SET description='指向直接父类的引用：super.成员 访问父类成员、super(...) 在子类构造首行调用父类构造，是父子类协作的桥梁。' WHERE kp_code='kp-m3-l3-004';
UPDATE knowledge_point SET description='最终修饰符：修饰类不可被继承、修饰方法不可被重写、修饰变量成为常量不可再赋值；配合 static 定义全局常量（如 static final double PI）。' WHERE kp_code='kp-m3-l3-005';
UPDATE knowledge_point SET description='含抽象方法、不能实例化的模板类，为子类定义规范骨架，介于具体类与接口之间，实现抽象层面的复用设计。' WHERE kp_code='kp-m3-l2-002';
UPDATE knowledge_point SET description='用 abstract 修饰、可包含抽象方法的类，在表达“是什么”的同时把实现细节留给子类，只能被继承不能被 new。' WHERE kp_code='kp-m3-l3-006';
UPDATE knowledge_point SET description='“abstract class 类名{}”，可包含普通方法、构造方法与成员变量，构造方法供子类 super 调用，类自身无法实例化。' WHERE kp_code='kp-m3-l3-007';
UPDATE knowledge_point SET description='“abstract 返回类型 方法名(参数);”，只有方法声明没有方法体，存在于抽象类中，子类必须全部重写否则自身也须声明为抽象。' WHERE kp_code='kp-m3-l3-008';
UPDATE knowledge_point SET description='典型如模板方法模式：父类定义算法骨架并声明抽象步骤，子类实现各自的步骤细节，如 Animal 定义 eat() 由各子类具体实现。' WHERE kp_code='kp-m3-l3-009';
UPDATE knowledge_point SET description='同一引用调用同一方法呈现不同行为的特性，“编译看左边、运行看右边”，是面向对象灵活性与可扩展性的集中体现。' WHERE kp_code='kp-m3-l2-003';
UPDATE knowledge_point SET description='引用类型之间的向上与向下转型，配合 instanceof 类型判断，是多态安全使用的前提。' WHERE kp_code='kp-m3-l3-010';
UPDATE knowledge_point SET description='子类对象赋给父类引用（Animal a = new Dog()），自动完成且安全，但该引用只能调用父类声明的成员，是多态的基础。' WHERE kp_code='kp-m3-l4-001';
UPDATE knowledge_point SET description='父类引用强转回子类类型（(Dog) a），可恢复调用子类特有方法，但须先用 instanceof 确认真实类型，否则抛出 ClassCastException。' WHERE kp_code='kp-m3-l4-002';
UPDATE knowledge_point SET description='“引用 instanceof 类型” 判断对象的运行时真实类型并返回 boolean，是向下转型前的安全检查，避免类型转换异常。' WHERE kp_code='kp-m3-l3-011';
UPDATE knowledge_point SET description='前提为继承+重写+向上转型；父类引用调用被重写方法时执行实际子类的版本，新增子类无需修改调用代码，体现开闭原则。' WHERE kp_code='kp-m3-l3-012';
UPDATE knowledge_point SET description='定义行为契约的引用类型，抽象方法默认 public abstract，Java 8 起支持 default/static 方法，是实现解耦设计的核心工具。' WHERE kp_code='kp-m3-l2-004';
UPDATE knowledge_point SET description='一组行为规范的抽象集合，定义“能做什么”，类通过实现接口获得能力，弥补单继承限制实现多种能力的组合。' WHERE kp_code='kp-m3-l3-013';
UPDATE knowledge_point SET description='“interface 接口名{}”，成员变量默认 public static final，抽象方法默认 public abstract，Java 8 之后可含 default 与 static 方法。' WHERE kp_code='kp-m3-l3-014';
UPDATE knowledge_point SET description='类通过 implements 实现接口并重写全部抽象方法，可同时实现多个接口（逗号分隔），接口之间可以多继承。' WHERE kp_code='kp-m3-l3-015';
UPDATE knowledge_point SET description='面向接口编程：依赖声明为接口类型而非具体实现（如 List l = new ArrayList()），替换实现不动调用方，常用于回调与解耦分层。' WHERE kp_code='kp-m3-l3-016';
UPDATE knowledge_point SET description='定义在类或方法内部的类，分成员、局部、匿名与静态四种，可实现外部类私有成员访问与回调封装等设计需求。' WHERE kp_code='kp-m3-l2-005';
UPDATE knowledge_point SET description='位于类中方法外，持有外部类引用，可直接访问外部类成员（含私有），以 Outer.Inner 形式存在，每个实例关联一个外部对象。' WHERE kp_code='kp-m3-l3-017';
UPDATE knowledge_point SET description='定义在方法或代码块内，仅在该方法内可见可用，可访问外部类成员以及所在方法的 effectively final 局部变量。' WHERE kp_code='kp-m3-l3-018';
UPDATE knowledge_point SET description='无类名、声明同时实例化的临时实现（new 接口/父类(){实现}），常用于事件监听、Runnable 线程等一次性实现场景，简化代码。' WHERE kp_code='kp-m3-l3-019';
UPDATE knowledge_point SET description='static 修饰的嵌套类，不持有外部类引用、只能访问外部静态成员，实例化无需外部实例，适合纯命名空间式的组织。' WHERE kp_code='kp-m3-l3-020';
UPDATE knowledge_point SET description='程序运行时错误的面向对象处理机制：Throwable 分为 Error 与 Exception，通过 try/catch/finally 捕获处理或 throws 声明抛出。' WHERE kp_code='kp-m3-l2-006';
UPDATE knowledge_point SET description='Java 以异常对象封装错误信息，通过 try 监控、catch 捕获处理、finally 兜底清理，或 throws 转交调用方，保证异常路径下程序可控。' WHERE kp_code='kp-m3-l3-021';
UPDATE knowledge_point SET description='Throwable 为根，分为 Error（JVM 级致命错误）与 Exception（程序可处理），Exception 再分为受检异常与运行时异常（RuntimeException）。' WHERE kp_code='kp-m3-l3-022';
UPDATE knowledge_point SET description='Error 无需捕获（如 StackOverflowError）；受检异常（如 IOException）编译器强制处理；运行时异常（如 NPE）多因逻辑缺陷应从源头避免。' WHERE kp_code='kp-m3-l3-023';
UPDATE knowledge_point SET description='try 包裹可能出错的代码，catch 按类型捕获并以 e.getMessage() 获取信息，finally 无论是否发生异常都会执行，常用于释放资源。' WHERE kp_code='kp-m3-l3-024';
UPDATE knowledge_point SET description='throws 在方法签名声明不处理的异常类型转交调用方；throw 语句手动抛出异常对象，常用于业务校验失败（throw new XxxException(msg)）。' WHERE kp_code='kp-m3-l3-025';
UPDATE knowledge_point SET description='继承 Exception（受检）或 RuntimeException（运行时）定义业务异常，携带语义化字段，让错误处理贴合业务含义（如年龄非法异常）。' WHERE kp_code='kp-m3-l3-026';

-- ============ 模块四：集合与Java核心API ============
UPDATE knowledge_point SET description='Java 常用核心类库与集合框架模块，覆盖 Object/String/时间等基础 API、Lambda 表达式、泛型与 Stream API，是日常开发的主力工具集。' WHERE kp_code='kp-m4-l1-001';
UPDATE knowledge_point SET description='JDK 官方提供的基础类库集合，掌握常用类的功能定位与核心用法是高效编码的基础。' WHERE kp_code='kp-m4-l2-001';
UPDATE knowledge_point SET description='所有类的隐式最终祖先，定义了 equals/hashCode/toString/getClass/clone 等根方法，重写 equals 时必须同时重写 hashCode。' WHERE kp_code='kp-m4-l3-001';
UPDATE knowledge_point SET description='不可变字符序列，双引号字面量进常量池复用；+ 拼接低效应改用 StringBuilder；equals 比较内容、== 比较地址，是使用最频繁的类。' WHERE kp_code='kp-m4-l3-002';
UPDATE knowledge_point SET description='系统级静态工具类，核心包括 out/in 标准流、currentTimeMillis 计时、arraycopy 数组复制、exit 退出及 getProperty 属性读取。' WHERE kp_code='kp-m4-l3-003';
UPDATE knowledge_point SET description='java.time 下的不可变日期类（精确到日），now/of 创建、plus/minus 偏移、DateTimeFormatter 格式化，替代旧的 Date/Calendar。' WHERE kp_code='kp-m4-l3-004';
UPDATE knowledge_point SET description='精确到时间（时:分:秒.纳秒）的不可变类，now/of 创建，支持 plus/minus、with 修改及比较运算，常与 LocalDate 组合使用。' WHERE kp_code='kp-m4-l3-005';
UPDATE knowledge_point SET description='java.time 的格式化与解析工具，ofPattern("yyyy-MM-dd HH:mm:ss") 定义格式，format() 转字符串、parse() 转回时间对象，线程安全。' WHERE kp_code='kp-m4-l3-006';
UPDATE knowledge_point SET description='基于秒与纳秒的时长类，between(开始,结束) 计算时间差，toHours/toMinutes/toDays 转换单位，适合机器级精确计时。' WHERE kp_code='kp-m4-l3-007';
UPDATE knowledge_point SET description='基于年月日的日期差类，between(开始日期,结束日期) 得到年/月/日三段差值，适合年龄、工期等人类可读的间隔计算。' WHERE kp_code='kp-m4-l3-008';
UPDATE knowledge_point SET description='日期与时间的组合类型（年月日时分秒纳秒），now/of 创建，支持 plus/minus/with 修改及格式化，是 java.time 最常用的时间类型。' WHERE kp_code='kp-m4-l3-009';
UPDATE knowledge_point SET description='“(参数) -> 表达式/代码块”的函数式写法，用于实现单抽象方法接口（函数式接口），配合 Stream 大幅简化匿名内部类代码。' WHERE kp_code='kp-m4-l3-010';
UPDATE knowledge_point SET description='伪随机数生成器：nextInt(n) 生成 [0,n) 整数、nextInt() 全域整数，指定种子可复现序列，与 Math.random() 是两条使用路线。' WHERE kp_code='kp-m4-l3-011';
UPDATE knowledge_point SET description='数学静态工具类：abs/max/pow/sqrt/round/floor/ceil 等方法及 PI/E 常量，方法全部为 static，构造方法已私有化不可实例化。' WHERE kp_code='kp-m4-l3-012';
UPDATE knowledge_point SET description='字符串查找与匹配：indexOf/lastIndexOf 定位子串、contains 判断包含、startsWith/endsWith 判断前后缀，配合 matches 支持正则模式匹配。' WHERE kp_code='kp-m4-l3-013';
UPDATE knowledge_point SET description='动态长度的容器框架：Collection（List 有序可重复 / Set 去重）与 Map（键值对）两大体系，替代定长数组处理变长数据。' WHERE kp_code='kp-m4-l2-002';
UPDATE knowledge_point SET description='有序、可重复的 Collection 分支，通过索引精确访问，实现类 ArrayList（数组结构、查询快）与 LinkedList（链表结构、增删快）。' WHERE kp_code='kp-m4-l3-014';
UPDATE knowledge_point SET description='不允许重复元素的 Collection 分支，依赖 equals 与 hashCode 判重，实现类 HashSet（哈希无序）与 TreeSet（自动排序）。' WHERE kp_code='kp-m4-l3-015';
UPDATE knowledge_point SET description='基于哈希表实现的无序去重集合，增删查 O(1)，要求元素正确重写 hashCode 与 equals，允许存放一个 null。' WHERE kp_code='kp-m4-l4-001';
UPDATE knowledge_point SET description='基于红黑树实现的排序 Set，支持自然排序与定制排序两种方式，增删查 O(log n)，元素须实现 Comparable 或传入 Comparator。' WHERE kp_code='kp-m4-l4-002';
UPDATE knowledge_point SET description='键值对映射容器：键唯一（重复 put 覆盖旧值）、值可重复；核心方法 put/get/remove/keySet/entrySet，实现类 HashMap/TreeMap/LinkedHashMap。' WHERE kp_code='kp-m4-l3-016';
UPDATE knowledge_point SET description='List/Set 可用 for-each 或 Iterator（hasNext/next，可安全 remove）遍历；Map 通过 keySet、values 或 entrySet 遍历（推荐 entrySet 一次取键值）。' WHERE kp_code='kp-m4-l3-017';
UPDATE knowledge_point SET description='参数化类型机制：类/接口/方法可声明类型参数（如 List<String>、<T,V>），编译期类型检查消除强制转换，是集合与框架的基石。' WHERE kp_code='kp-m4-l2-003';
UPDATE knowledge_point SET description='声明式数据处理管道（Java 8+）：集合.stream() 建流 → filter/map 中间操作惰性求值 → collect/reduce 终结操作，配合 Lambda 实现链式处理。' WHERE kp_code='kp-m4-l2-004';

-- ============ 模块五：持久化 ============
UPDATE knowledge_point SET description='数据持久化模块，涵盖 I/O 流与 JDBC 两大体系，完成文件读写与数据库交互，是应用数据落地的最后一块拼图。' WHERE kp_code='kp-m5-l1-001';
UPDATE knowledge_point SET description='按字节/字符流动处理数据的输入输出体系，分节点流与包装流（装饰器模式），File 类是文件操作的起点。' WHERE kp_code='kp-m5-l2-001';
UPDATE knowledge_point SET description='java.io.File 抽象文件与目录路径，支持 create/delete/rename、exists/isDirectory、mkdirs 及 listFiles 遍历，是文件操作的基础入口。' WHERE kp_code='kp-m5-l3-001';
UPDATE knowledge_point SET description='以字节为单位的通用流体系（InputStream/OutputStream 抽象根），可处理任意文件（图片、音视频等），read/write 按 8 位收发。' WHERE kp_code='kp-m5-l3-002';
UPDATE knowledge_point SET description='文件字节输入流：read() 单字节、read(byte[]) 批量读取，须处理 IOException 且在 finally 或 try-with-resources 中关闭。' WHERE kp_code='kp-m5-l4-001';
UPDATE knowledge_point SET description='文件字节输出流：write 写出数据（new FOS(f,true) 为追加模式），目标文件不存在则自动创建，配合 FIS 可实现文件复制。' WHERE kp_code='kp-m5-l4-002';
UPDATE knowledge_point SET description='以字符为单位的文本处理流体系（Reader/Writer 抽象根），内部按编码解码，适合文本文件处理，避免字节流读中文出现乱码。' WHERE kp_code='kp-m5-l3-003';
UPDATE knowledge_point SET description='文件字符输入流：read() 单字符、read(char[]) 批量读入，按平台默认编码解码文本，是纯文本读取的首选。' WHERE kp_code='kp-m5-l4-003';
UPDATE knowledge_point SET description='文件字符输出流：write 写出字符或字符串，flush() 冲刷缓冲后 close() 关闭，是文本写入的首选方式。' WHERE kp_code='kp-m5-l4-004';
UPDATE knowledge_point SET description='包装节点流的处理流（装饰器模式），内置缓冲区减少底层 IO 次数，BufferedReader 的 readLine 整行读取是文本处理利器。' WHERE kp_code='kp-m5-l3-004';
UPDATE knowledge_point SET description='字节缓冲输入流：包装 FileInputStream 一次批量读入缓冲区（默认 8KB），大幅提升读取效率。' WHERE kp_code='kp-m5-l4-005';
UPDATE knowledge_point SET description='字节缓冲输出流：写出先进缓冲区，flush() 强制冲刷落盘，与 BufferedInputStream 配合是文件复制的提速标配。' WHERE kp_code='kp-m5-l4-006';
UPDATE knowledge_point SET description='对象序列化与反序列化流：ObjectOutputStream 写对象、ObjectInputStream 读回，类须实现 Serializable，是对象持久化与跨进程传输的基础。' WHERE kp_code='kp-m5-l3-005';
UPDATE knowledge_point SET description='序列化输出流：writeObject(obj) 将对象按二进制写至目标流，transient 字段不参与序列化，serialVersionUID 保证版本兼容。' WHERE kp_code='kp-m5-l4-007';
UPDATE knowledge_point SET description='反序列化输入流：readObject() 读取二进制重建对象，要求对应类的 serialVersionUID 一致，是深拷贝与缓存落盘的常用手段。' WHERE kp_code='kp-m5-l4-008';
UPDATE knowledge_point SET description='Java 访问关系数据库的标准 API：Connection/Statement/ResultSet 六步流程 + PreparedStatement 防注入 + 连接池复用，是持久层的基础。' WHERE kp_code='kp-m5-l2-002';
UPDATE knowledge_point SET description='标准六步：加载驱动 → 获取 Connection → 创建 Statement → 执行 SQL 得 ResultSet → 处理结果 → 逆序关闭资源（try-with-resources 可简化）。' WHERE kp_code='kp-m5-l3-006';
UPDATE knowledge_point SET description='预编译语句：SQL 用 ? 占位、setXxx 设参，编译一次重复执行效率高，参数经转义从根本上防止 SQL 注入，应替代普通 Statement。' WHERE kp_code='kp-m5-l3-007';
UPDATE knowledge_point SET description='复用 Connection 的缓冲池技术：避免频繁建连销毁的开销，初始化预建+借出归还+超时回收，配合超时、上限等参数调优。' WHERE kp_code='kp-m5-l3-008';
UPDATE knowledge_point SET description='主流开源连接池实现：DBCP 轻量经典、C3P0 传统稳定、Druid 阿里出品带监控与防注入（推荐），核心配置为四大连接参数与初始/最大连接数。' WHERE kp_code='kp-m5-l4-009';
UPDATE knowledge_point SET description='Apache Commons DbUtils 工具库：QueryRunner 简化增删改查，ResultSetHandler（BeanHandler/BeanListHandler）自动映射结果集到对象，消除样板代码。' WHERE kp_code='kp-m5-l3-009';
